				checkSoughtNext();
				if (next == null) {
					throw new NoSuchElementException();
				}
				return next;
			}

			/* @Override */
			public DR next() {
				checkSoughtNext();
				soughtNext = false;
				return next;
			}
		
	}


	internal class _Anon_TreeRecordVisitor_2, TreeRecordVisitor
	{

			int count = 0);

			/* @Override */
			protected VisitResult beginNode(NR parent, NR n, QueryInclusion inclusion) {
				if (inclusion == QueryInclusion.NONE) {
					return VisitResult.NEXT;
				}
				if (inclusion == QueryInclusion.ALL) {
					count += n.getDataCount();
					return VisitResult.NEXT;
				}
				return VisitResult.DESCEND;
			}

			/* @Override */
			protected VisitResult visitData(NR parent, DR d, bool included) {
				if (included) {
					count++;
				}
				return VisitResult.NEXT;
			}
		
	}


