			}
		
	}


	internal class _Anon_TreeRecordVisitor_6 : TreeRecordVisitor
	{

			DR result;

			/* @Override */
			protected VisitResult beginNode(NR parent, NR n, QueryInclusion inclusion) {
				if (comparator != null && comparator.compare(shape.getBounds(), n.getShape()) < 0) {
					return VisitResult.ASCEND;
				}
				if (inclusion == QueryInclusion.NONE) {
					return VisitResult.NEXT;
				}
				if (!n.getShape().encloses(shape.getBounds())) {
					return VisitResult.NEXT;
				}
				return VisitResult.DESCEND;
			}

			/* @Override */
			protected VisitResult visitData(NR parent, DR d, bool included) {
				if (comparator != null &&
					comparator.compare(shape.getBounds(), d.getBounds()) <= 0) {
					return VisitResult.ASCEND;
				}
				if (!included) {
					return VisitResult.NEXT;
				}
				if (!d.shapeEquals(shape)) {
					return VisitResult.NEXT;
				}
				if (!value.equals(d.getRecordValue())) {
					return VisitResult.NEXT;
				}
				result = d;
				return VisitResult.TERMINATE;
			}
		
	}


	internal class _Anon_TreeRecordVisitor_7 : TreeRecordVisitor
	{

			/* @Override */
			protected VisitResult beginNode(NR parent, NR n, QueryInclusion inclusion) {
				return VisitResult.DESCEND;
			}

			/* @Override */
			protected VisitResult visitData(NR parent, DR d, bool included) {
				dataStore.delete(d);
				return VisitResult.NEXT;
			}

			/* @Override */
			protected VisitResult endNode(NR parent, NR n, QueryInclusion inclusion) {
				if (n.getType() == NodeType.LEAF) {
					cachedDataChildren.remove(n.getKey());
				}
				else {
					cachedNodeChildren.remove(n.getKey());
				}
				nodeStore.delete(n);
				return VisitResult.NEXT;
			}
		
	}


	internal class _Anon_TreeRecordVisitor_8 : TreeRecordVisitor
	{

			Set<NR> dirty = new();

			/* @Override */
			protected VisitResult beginNode(NR parent, NR n, QueryInclusion inclusion) {
				if (inclusion == QueryInclusion.NONE) {
					return VisitResult.NEXT;
				}
				if (inclusion == QueryInclusion.ALL) {
					if (n == root) {
						cachedDataChildren.clear();
						cachedNodeChildren.clear();
						dataStore.deleteAll();
						nodeStore.deleteAll();
						root = null;
						init();
						return VisitResult.TERMINATE;
					}
					dirty.add(parent);
					doRemoveFromCachedChildren(parent.getKey(), n, cachedNodeChildren);
					destroySubtree(n);
					return VisitResult.NEXT;
				}
				return VisitResult.DESCEND;
			}

			/* @Override */
			protected VisitResult visitData(NR parent, DR d, bool included) {
				if (!included) {
					return VisitResult.NEXT;
				}
				dirty.add(parent);
				doRemoveFromCachedChildren(parent.getKey(), d, cachedDataChildren);
				dataStore.delete(d);
				return VisitResult.NEXT;
			}

			/* @Override */
			protected VisitResult endNode(NR parent, NR n, QueryInclusion inclusion) {
				if (dirty.remove(n)) {
					resyncMetadata(n);
					dirty.add(parent);
				}
				return VisitResult.NEXT;
			}

			/* @Override */
			protected Iterator<NR> iterateNodes(Stream<NR> nodes) {
				return nodes.toList().iterator();
			}

			/* @Override */
			protected Iterator<DR> iterateData(Stream<DR> data) {
				return data.toList().iterator();
			}
		
	}


	internal class _Anon_TreeRecordVisitor_9 : TreeRecordVisitor
	{

			string getLevel(DBTreeRecord<object,object> record) {
				string level = "";
				NR parent = getParentOf(record);
				while (parent != null) {
					level = level + "  ";
					parent = getParentOf(parent);
				}
				return level;
			}

			/* @Override */
			protected VisitResult beginNode(NR parent, NR n, QueryInclusion inclusion) {
				Console.WriteLine(getLevel(n) + n + ": (" + inclusion + ")");
				if (inclusion == QueryInclusion.NONE) {
					return VisitResult.NEXT;
				}
				return VisitResult.DESCEND;
			}

			/* @Override */
			protected VisitResult visitData(NR parent, DR d, bool included) {
				Console.WriteLine(getLevel(d) + d + ": (" + included + ")");
				return VisitResult.NEXT;
			}
		
	}


